sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float intensity;
layout(color) uniform half4 color;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0 || blur <= 0.0) return src;
    float g = clamp((1.0 - float(blurred.eval(coord).a)) * 2.0 * intensity, 0.0, 1.0) * float(color.a);
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = base + float3(color.rgb) * g - base * float3(color.rgb) * g;
    return half4(half3(rgb) * src.a, src.a);
}
